import { Footercomp } from "Hindi-olabsnxtg-library";
import { Headcomp } from "Hindi-olabsnxtg-library";
import { Middlecomp } from "Hindi-olabsnxtg-library";
import React from "react";
import hindi_bg from "../Img/hindi_bg.jpg";
import * as Instru from "../components/Instruction";
import { useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import { useTranslation } from "react-i18next";
import Level2 from "./Level2.js";
import ReactGA from "react-ga4";
import QuizPopupContent from "../quiz/QuizPopupContent";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import IconButton from "@mui/material/IconButton";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import Box from "@mui/material/Box";

const LL5_level_2 = () => {
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const { t, i18n } = useTranslation();
  const [instruct, setInstruct] = useState(Instru.Instruction_3(t));

  ReactGA.send({
    hitType: "pageview",
    page: "#/ll5_level2",
    title: "L10 | Level2_samas",
  });

  return (
    <div
      style={{
        height: "100vh",
        backgroundImage: "url(" + hindi_bg + ")",
        backgroundSize: "100% 100%",
        backgroundRepeat: "no-repeat",
        maxHeight: "100%",
      }}
    >
      <Headcomp
        H_title={t("title")}
        H_sidebarvisible="true"
        HQ_quittext={t("quitpopup")}
        HQ_yes={t("yes")}
        HQ_cancel={t("cancel")}
        RSM_QuizPopupContent_comp={<QuizPopupContent />}
        RSM_Intruc_popup_title_string={t("quizpophead")}
        RSM_ok={t("yes")}
        RSM_menu_tt={t("menu")}
        RSM_theory_tt={t("theory")}
        RSM_vivavoce_tt={t("vivavoce")}
        RSM_procedure_tt={t("quiz")}
        RSM_help_tt={t("help")}
        WS_sendJsonMessage={sendJsonMessage}
        WS_sendLogData={SendLogData}
        L_labName={t("title")}
        L_labUniqueName="CDAC-OlabsNxtG-Hindi-Lab-10"
      />

      <Footercomp
        F_footheight="15%"
        F_instruction={instruct}
        F_instructionlabel={t("instuhead")}
      />

      <br />

      <Middlecomp
        M_midheight="70%"
        M_midcontent={
          <Level2
            changeInst={(e) => {
              setInstruct(e);
            }}
          />
        }
      />
      <ToastContainer />
    </div>
  );
};

export default LL5_level_2;
