import React, { useEffect, useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@material-ui/core";
import DialogContentText from "@mui/material/DialogContentText";
import { Button, IconButton, Slider, Tooltip } from "@mui/material";
import Dropdown from "react-bootstrap/Dropdown";
import jsondata from "../level2.json";
import { IoIosInformationCircle } from "react-icons/io";
import { MdDelete } from "react-icons/md";
import Paper from "@mui/material/Paper";
import Grid from "@mui/material/Grid";
import { styled } from "@mui/material/styles";
import arrayShuffle from "array-shuffle";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import Swal from "sweetalert2";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import { all } from "axios";
import info from "../Img/i_image.png";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";

function L2T1() {
  const parse = require("html-react-parser").default;
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  const [mainarr, setMainarr] = useState(Object.values(jsondata.data));
  const [currpara, setCurrpara] = useState();
  const [currcorrpara, setCurrcorrpara] = useState();
  var [parano, setParano] = useState(0);
  const [punctuations, setPunctuations] = useState(
    arrayShuffle(jsondata.punctuation_marks)
  );
  const [currmarksfeedback, setCurrmarksfeedback] = useState();
  const [currfeedback, setCurrfeedback] = useState();
  const [table, setTable] = useState(jsondata.table);

  const [flag, setFlag] = useState(true);
  const [flag1, setFlag1] = useState(false);
  const [flag2, setFlag2] = useState(false);
  const [flag3, setFlag3] = useState(false);
  var [score, setScore] = useState(0);
  var [open1, setOpen1] = useState(false);

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 2 page");

  const Item = styled(Paper)(({ theme }) => ({
    backgroundColor: "#F5B946",
    ...theme.typography.body2,
    // padding: theme.spacing(1.6),
    textAlign: "center",
    color: theme.palette.text.secondary,
    fontWeight: "bolder",
    fontSize: "20px",
    cursor: "grab",
    paddingRight: "1.5vh",
    paddingLeft: "1.5vh",
  }));

  useEffect(() => {
    if (parano > mainarr.length - 1) {
      setFlag3(true);
    } else {
      const tempWords = mainarr[parano].paragraph.split(" ");
      const tempcorrectpara = mainarr[parano].correct_para.split(" ");
      const updatedPara = [];
      const updatedcorrPara = [];

      tempWords.forEach((word) => {
        let punctFound = false;
        punctuations.forEach((mark) => {
          if (word.includes(mark.mark)) {
            const splitParts = word.split(mark.mark).filter(Boolean); // remove empty strings
            splitParts.forEach((part, i) => {
              updatedPara.push(part);
              if (i < splitParts.length - 1 || word.endsWith(mark.mark)) {
                updatedPara.push(mark.mark);
              }
            });
            punctFound = true;
          }
        });
        if (!punctFound) updatedPara.push(word);
      });

      tempcorrectpara.forEach((word) => {
        let punctFound = false;
        punctuations.forEach((mark) => {
          if (word.includes(mark.mark)) {
            const splitParts = word.split(mark.mark).filter(Boolean); // remove empty strings
            splitParts.forEach((part, i) => {
              updatedcorrPara.push(part);
              if (i < splitParts.length - 1 || word.endsWith(mark.mark)) {
                updatedcorrPara.push(mark.mark);
              }
            });
            punctFound = true;
          }
        });
        if (!punctFound) updatedcorrPara.push(word);
      });

      setCurrpara(updatedPara);
      setCurrcorrpara(updatedcorrPara);
      setCurrmarksfeedback(mainarr[parano].correct_marks);
      console.log("currcorrpara ==>", currcorrpara);
    }
  }, [parano]);

  console.log("currmarksfeedback ==>", currmarksfeedback);

  const level1select = () => {
    ReactGA.event({
      action:
        "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on level-1 dropdown button.",
      category:
        'English CDAC-OlabsNxtG-En-35 | level-2 "level-1" dropdown button clicked',
      label:
        'English CDAC-OlabsNxtG-En-35 | level-2 "level-1" dropdown button clicked to navigate to level-1.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-2 "level-1" dropdown button',
      "Clicked",
      'Level-2 "level-1" dropdown button clicked to navigate to level-1.'
    );
    navigate("/launchpage/englishactivity/level1");
  };

  const handleDrop = (e, index) => {
    const newItems = [...currpara];
    currpara.map((val, idx) => {
      if (index == idx) {
        newItems[index] = e.dragData;
      }
    });
    setCurrpara(newItems);
  };

  const handleverifybtn = () => {
    let allCorrect = true;

    currpara.forEach((currparaele, idx) => {
      const isPunctuation = punctuations.some(
        (obj) => obj.mark === currparaele
      );

      if (isPunctuation) {
        const correctele = currcorrpara[idx];
        const el = document.getElementById(`punct_${idx}`);
        if (!el) return;

        if (correctele === currparaele) {
          el.style.backgroundColor = "#c8e6c9"; // green
          el.style.color = "green";
        } else {
          el.style.backgroundColor = "#ffcdd2"; // red
          el.style.color = "red";
          allCorrect = false;
        }
      }
    });

    if (allCorrect) {
      setFlag(false);
    }
    setFlag2(true);

    ReactGA.event({
      action:
        "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Verify button",
      category: "English CDAC-OlabsNxtG-En-35 | level-2 Verify button clicked",
      label:
        "English CDAC-OlabsNxtG-En-35 | level-2 Verify button clicked for checking dropped punctuation mark.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-2 "Verify" button',
      "Clicked",
      'Level-2 "Verify" button clicked for checking dropped punctuation mark.'
    );
  };

  const handleonClick = (e, val, idx) => {
    const correctMark = currcorrpara[idx]; // The expected punctuation at this index
    const feedbackObj = currmarksfeedback.find(
      (item) => item.mark === correctMark
    );

    setFlag1(true);

    if (correctMark !== val && feedbackObj) {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          गलत उत्तर! (<b style={{ color: "red" }}>{val}</b>) गलत विराम चिह्न है।
          <br />
          <b>संकेत</b>: {feedbackObj.meaning}
        </div>
      );
    } else {
      setCurrfeedback(
        <>
          सही उत्तर! &nbsp; <b style={{ color: "green" }}>{val}</b> &nbsp; सही
          विराम चिह्न है।
        </>
      );
    }
  };

  const handlenextbtn = () => {
    if (parano > mainarr.length - 1) {
      alert("all completed");
    } else {
      parano = parano + 1;
      setParano(parano);
      setFlag(true);
      setFlag1(false);
      setFlag2(false);

      for (let i = 0; i < currpara.length; i++) {
        const elem = document.getElementById(`punct_${i}`);
        if (elem) {
          // ✅ Only if element exists
          elem.style.backgroundColor = "lightblue";
        }
      }

      score = score + 1;
      setScore(score);

      ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Next button",
        category: "English CDAC-OlabsNxtG-En-35 | level-2 Next button clicked",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-2 Next button clicked for next paragraph.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Next" button',
        "Clicked",
        'Level-2 "Next" button clicked for next paragraph.'
      );
    }
  };

  const handleskipbtn = () => {
    if (parano > mainarr.length - 1) {
      alert("all completed");
    } else {
      parano = parano + 1;
      setParano(parano);
      setFlag(true);
      setFlag1(false);
      setFlag2(false);

      for (let i = 0; i < currpara.length; i++) {
        const elem = document.getElementById(`punct_${i}`);
        if (elem) {
          // ✅ Only if element exists
          elem.style.backgroundColor = "lightblue";
        }
      }

      ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-35 | level-2 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-2 Skip button clicked to skip current paragraph.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Skip" button',
        "Clicked",
        'Level-2 "Skip" button clicked to skip current paragraph.'
      );
    }
  };

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-35 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-35 | "Restart" button clicked and level 2 restarted.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and level 2 restarted.'
    );

    window.location.reload();
  };

  const handleinfobtn = () => {
    setOpen1(true);

    ReactGA.event({
      action:
        "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Help icon.",
      category: "English CDAC-OlabsNxtG-En-35 | level-2 help icon clicked.",
      label:
        "English CDAC-OlabsNxtG-En-35 | level-2 help icon clicked for additional punctuation mark information.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Level-2 Help icon",
      "Clicked",
      "Level-2 help icon clicked for additional punctuation mark information."
    );
  };

  const handleClose = () => {
    open1 = false;
    setOpen1(open1);
  };

  return (
    <div
      className="scrollbar-primary"
      style={{
        height: "100%",
        fontSize: "1rem",
        background: "#FCF5F5",
        borderRadius: "14px",
        overflow: "auto",
        overflowX: "hidden",
      }}
    >
      <div className="row d-flex align-items-center justify-content-center">
        {flag3 ? (
          <div
            className=""
            style={{
              // height: "80vh",
              // width: "100%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              // padding: "4%",
              paddingTop: "0%",
              overflow: "hidden",
              overflowX: "hidden",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex">
              <div>
                <h6
                  style={{
                    marginTop: "15%",
                    marginLeft: "1vh",
                    color: "#4E0870",
                  }}
                >
                  <strong>{t("level_2")}</strong>
                </h6>
              </div>
              <div className="col text-center">
                <h5 style={{ paddingTop: "10px", color: "#4E0870" }}>
                  <strong>अनुच्छेद में विराम चिह्न</strong>
                </h5>
              </div>

              <div className="col-md-auto">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle
                    variant="success"
                    id="dropdown-basic"
                    style={{ background: "#A372D1" }}
                  >
                    {t("level_selectbtn")}
                  </Dropdown.Toggle>
                  <Dropdown.Menu style={{ background: "#F7F1FC" }}>
                    <Dropdown.Item
                      href="#/ll5_level1"
                      style={{ color: "#350B5B" }}
                    >
                        स्तर 1
                    </Dropdown.Item>
                    <Dropdown.Item disabled>  स्तर 2</Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex justify-content-center align-items-center "
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  आपने सभी प्रयास पूरे कर लिए हैं, फिर से प्रयास करने के लिए
                  'पुनः आरंभ' बटन पर क्लिक करें।
                </p>
                <div>
                  <Button
                    style={{
                      borderRadius: "5px",
                      borderColor: "#4E0870",
                      color: "white",
                      backgroundColor: "#A372D1",
                      marginTop: "1%",
                    }}
                    onClick={restartbtn}
                  >
                    {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "100%vh",
              background: "#FFFFFF",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              // padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex">
              <div>
                <h6
                  style={{
                    marginTop: "15%",
                    marginLeft: "1vh",
                    color: "#4E0870",
                  }}
                >
                  <strong>{t("level_1")}</strong>
                </h6>
              </div>
              <div className="col text-center">
                <h5 style={{ paddingTop: "10px", color: "#4E0870" }}>
                  <strong>अनुच्छेद में विराम चिह्न</strong>
                </h5>
              </div>

              <div className="col-md-auto">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle
                    variant="success"
                    id="dropdown-basic"
                    style={{ background: "#A372D1" }}
                  >
                    {t("level_selectbtn")}
                  </Dropdown.Toggle>
                  <Dropdown.Menu style={{ background: "#F7F1FC" }}>
                    <Dropdown.Item
                      href="#/ll5_level1"
                      style={{ color: "#350B5B" }}
                    >
                      स्तर 1
                    </Dropdown.Item>
                    <Dropdown.Item disabled>स्तर 2</Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              style={{
                display: "flex",
                justifyContent: "end",
                marginTop: "1vh",
              }}
            >
              {/* <img src={info} title="Help" onClick={handleinfobtn}></img> */}
            </div>

            <div
              className="row-md-auto"
              style={{
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                alignItems: "center",
                padding: "2%",
                marginTop: "1vh",
                textAlign: "center",
              }}
            >
              {currpara != null
                ? currpara.map((ele, index) => {
                    const isPunctuation = punctuations.some(
                      (obj) => obj.mark === ele
                    );

                    return (
                      <span key={index}>
                        {isPunctuation ? (
                          <DropTarget
                            targetKey="punctuation"
                            onHit={
                              flag ? (e) => handleDrop(e, index) : () => {}
                            }
                          >
                            <span
                              className=""
                              style={{
                                border: "1px dashed gray",
                                paddingLeft: "5px",
                                paddingRight: "5px",
                                textAlign: "center",
                                cursor: "pointer",
                                backgroundColor: "lightblue",
                              }}
                              onClick={
                                flag2
                                  ? (e) => handleonClick(e, ele, index)
                                  : () => {}
                              }
                              id={`punct_${index}`}
                            >
                              {ele}&nbsp;
                            </span>
                          </DropTarget>
                        ) : (
                          <span>&nbsp; {parse(String(ele))}&nbsp;</span>
                        )}
                      </span>
                    );
                  })
                : "no data"}
            </div>
            <div className="d-flex justify-content-center">
              <div
                className="col-sm-6"
                style={{
                  borderRadius: "13px",
                  boxShadow: "0px 4px 7px #00000029",
                  marginTop: "1vh",
                }}
              >
                <div
                  className="d-flex justify-content-center "
                  style={{ textAlign: "start", paddingTop: "" }}
                >
                  <span className="text-center" style={{ paddingLeft: "5vh" }}>
                    <b>विराम चिह्न</b>
                  </span>
                </div>
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center", // Center contents horizontally
                  }}
                >
                  <Grid
                    container
                    spacing={{ xs: 2, md: 3 }}
                    justifyContent="center"
                    style={{
                      padding: "15px",
                      maxWidth: "600px", // Optional: controls max width
                    }}
                  >
                    {punctuations.length > 0 ? (
                      punctuations.slice(0, 5).map((mark, index) => (
                        <Grid item xs={2} sm={4} md={2} key={index}>
                          <Tooltip title={mark.name} arrow>
                            <span>
                              <DragDropContainer
                                targetKey="punctuation"
                                dragData={mark.mark}
                                onDragStart={() =>
                                  console.log(`Dragging ${mark.mark}`)
                                }
                              >
                                <Item>{mark.mark}</Item>
                              </DragDropContainer>
                            </span>
                          </Tooltip>
                        </Grid>
                      ))
                    ) : (
                      <p>No Data in shuffledmarks</p>
                    )}
                  </Grid>

                  <Grid
                    container
                    spacing={{ xs: 2, md: 3 }}
                    justifyContent="center"
                    style={{
                      marginTop: "5px",
                      padding: "15px",
                      maxWidth: "600px", // Optional
                    }}
                  >
                    {punctuations.length > 0 ? (
                      punctuations.slice(5, 8).map((mark, index) => (
                        <Grid item xs={2} sm={4} md={2} key={index}>
                          <Tooltip title={mark.name} arrow>
                            <span>
                              <DragDropContainer
                                targetKey="punctuation"
                                dragData={mark.mark}
                                onDragStart={() =>
                                  console.log(`Dragging ${mark.mark}`)
                                }
                              >
                                <Item>{mark.mark}</Item>
                              </DragDropContainer>
                            </span>
                          </Tooltip>
                        </Grid>
                      ))
                    ) : (
                      <p>No Data in shuffledmarks</p>
                    )}
                  </Grid>
                </div>
              </div>
            </div>
            <div className="d-flex justify-content-around mt-4">
              <Button
                style={{
                  borderColor: "#4E0870",
                  color: "white",
                  backgroundColor: "#A372D1",
                }}
                onClick={handleskipbtn}
              >
                छोड़ दे
              </Button>
              <Button
                style={{
                  borderColor: "#4E0870",
                  color: "white",
                  backgroundColor: "#A372D1",
                }}
                onClick={handleverifybtn}
              >
                जाँच करें
              </Button>

              <Button
                onClick={handlenextbtn}
                style={{
                  borderColor: "#4E0870",
                  color: "white",
                  // backgroundColor: "#A372D1",
                  backgroundColor: flag ? "#D3D3D3" : "#A372D1",
                }}
                disabled={flag}
              >
                अगला वाक्य
              </Button>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag1 ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {currfeedback}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <Dialog
        open={open1}
        onClose={handleClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle
          id="alert-dialog-title"
          style={{ backgroundColor: "#90D5FF" }}
        >
          Punctuation marks meanings
        </DialogTitle>

        <table style={{ margin: "2vh", border: "1px solid black" }}>
          <tr style={{ textAlign: "center", border: "1px solid black" }}>
            <th style={{ borderRight: "1px solid black" }}>
              Punctuation Marks
            </th>
            <th>Meanings</th>
          </tr>
          {table.length != 0
            ? table.map((item, index) => {
                return (
                  <tr
                    key={index}
                    style={{ textAlign: "center", border: "1px solid black" }}
                  >
                    <td style={{ borderRight: "1px solid black" }}>
                      {item.punctuation}
                    </td>
                    <td>{item.meaning}</td>
                  </tr>
                );
              })
            : ""}
        </table>
        <DialogActions>
          <Button onClick={handleClose} variant="contained">
            Ok
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

export default L2T1;
