import React from "react";
import { useTranslation } from "react-i18next";
import redfort from "../Img/redfort.png";
import farm from "../Img/farm.png";
import butterfly from "../Img/butterfly.png";
import football from "../Img/football.png";
import old from "../Img/old.png";
import sursagar from "../Img/sursagar.png";
import "../styles/common.css";

const AltheoryMidContent1 = () => {
  const { t, i18n } = useTranslation();

  return (
    <div
      className=""
      style={{ height: "100%", width: "100%", fontFamily: "arial" }}
    >
      <div
        className="d-flex justify-content-center"
        style={{
          fontWeight: "bold",
          fontSize: "calc(0.26rem + 1.3vw)",
          height: "6%",
        }}
      >
        पाठ
      </div>
      <div
        className="bg-inf overflow-auto scrollbar-primary"
        style={{ height: "94%" }}
      >
        <div className="col mt-2">
          <div className="" style={{ marginLeft: "2%" }}>
            <div className="">
              <b>{t("Objective")}</b>
            </div>
            <div className="">विराम-चिह्न को पहचानना।</div>
            <br></br>
            <div className="">
              <b>{t("Theory_hd_1")}</b>
            </div>
            <div className="">
              वाक्यों को पढ़ते या बोलते समय एक या एक से अधिक स्थानों पर ठहरना
              पड़ता है। ठहरने के इन स्थानों को विराम कहते हैं, और लिखते समय इन
              स्थानों पर जिन चिह्नों का प्रयोग होता है, उन्हें{" "}
              <b>विराम-चिह्न</b> कहते हैं।
            </div>{" "}
            <br></br>
            <h6>
              <strong>प्रमुख विराम चिह्न देखे -</strong>
            </h6>
            <div className="container mt-4 d-flex justify-content-start">
              <table
                className="table table-bordered table-striped text-center"
                style={{ width: "60%" }}
              >
                <thead className="">
                  <tr>
                    <th scope="col">क्रमांक</th>
                    <th scope="col">विराम चिह्न / अर्थ</th>
                    <th scope="col">प्रतीक</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <th scope="row">1</th>
                    <td>पूर्ण विराम (Full Stop)</td>
                    <td>।</td>
                  </tr>
                  <tr>
                    <th scope="row">2</th>
                    <td>अल्प विराम (Comma)</td>
                    <td>,</td>
                  </tr>
                  <tr>
                    <th scope="row">3</th>
                    <td>अर्ध विराम (Semi-Colon)</td>
                    <td>;</td>
                  </tr>
                  <tr>
                    <th scope="row">4</th>
                    <td>प्रश्नवाचक चिह्न (Interrogation)</td>
                    <td>?</td>
                  </tr>
                  <tr>
                    <th scope="row">5</th>
                    <td>विस्मयादिबोधक / संबोधन (Exclamation)</td>
                    <td>!</td>
                  </tr>
                  <tr>
                    <th scope="row">6</th>
                    <td>योजक चिह्न (Hyphen)</td>
                    <td>-</td>
                  </tr>
                  <tr>
                    <th scope="row">7</th>
                    <td>विवरण चिह्न (Sign of Following)</td>
                    <td>:-</td>
                  </tr>
                  <tr>
                    <th scope="row">8</th>
                    <td>उपविराम (Colon)</td>
                    <td>:</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <br></br>
            {/* <ol>
                <li>पूर्ण विराम (Full Stop) ( । )</li>
                <li>अल्प विराम (Comma) ( , )</li>
                <li>अर्ध विराम (Semi-Colon) ( ; )</li>
                <li>प्रश्नवाचक चिह्न (Sign of Interrogation) (?)</li>
                <li>विस्मयादिबोधक या संबोधन (Sign of Exclamation) ( ! )</li>
                <li>योजक चिह्न (Hyphen) (-)</li>
                <li>विवरण चिह्न ( Sign of following ) (:-)</li>
                <li>उपविराम ( Colon ) (:)</li>
              </ol> */}
            <div className="heading">
              <strong>1. पूर्ण विराम (Full Stop) ( । )</strong>
            </div>
            <div className="def">
              पूर्ण विराम का अर्थ है पूरा ठहराव। इस चिह्न का प्रयोग वाक्य के
              पूरा हो जाने पर किया जाता है; जैसे -{" "}
              <b>में प्रतिदिन खेलता हूँ।</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>2. अल्प विराम (Comma) ( , )</strong>
            </div>
            <div className="def">
              अर्ध विराम का अर्थ होता है - थोड़ा ठहराव। यह पूर्ण विराम की तुलना
              में कम समय के ठहराव को दर्शाने के लिए उपयोग किया जाता है; जैसे -
              <b> परीक्षा निकट है, इसलिए अधिक परिश्रम करो।</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>3. अर्ध विराम (Semi-Colon) ( ; )</strong>
            </div>
            <div className="def">
              अल्प विराम का अर्थ है - बहुत ही थोड़ा ठहराव। इसका ठहराव अर्ध विराम
              से भी कम होता है; जैसे - <b>मोहन, राम, सरिता और महेश घूमने गए।</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>4. प्रश्नवाचक चिह्न (Sign of Interrogation) (?)</strong>
            </div>
            <div className="def">
              प्रश्नसूचक वाक्यों के अंत में हमेशा प्रश्नवाचक चिह्न लगाया जाता
              है; जैसे - <b>क्या आप उनकी सहायता करेंगे?</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>
                5. विस्मयादिबोधक या संबोधन (Sign of Exclamation) ( ! )
              </strong>
            </div>
            <div className="def">
              जब वाक्य में हर्ष, दुःख, शोक, आश्चर्य, घृणा आदि जैसी भावनाएं
              व्यक्त होती हैं, तब उसके अंत में विस्मयादिबोधक चिह्न (!) का प्रयोग
              किया जाता है। जैसे -{" "}
              <b>वाह! कितना मज़ा आ रहा है।, ईश्वर तुम्हारा भला करें।</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>6. योजक चिह्न (Hyphen) (-)</strong>
            </div>
            <div className="def">
              इस चिह्न का उपयोग तब किया जाता है जब दो शब्दों को जोड़ा जाता है
              (शब्द-युग्म), तत्पुरुष और द्वंद्व समास में, तुलनात्मक शब्दों (सा,
              सी, से) से पहले, और अक्षरों में लिखी संख्याओं के भागों को अलग करने
              के लिए। जैसे - <b>सुख-दुख, यश-अपयश, भाई-बहन</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>7. विवरण चिह्न ( Sign of following ) (:-)</strong>
            </div>
            <div className="def">
              जब किसी कथन या प्रश्न का उत्तर अगली पंक्ति में विस्तार से दिया
              जाता है, तो वहाँ विवरण चिह्न (:) का प्रयोग किया जाता है। जैसे -
              <b>विवरण इस प्रकार है :-</b>
            </div>
            <br></br>
            <div className="heading">
              <strong>उपविराम ( Colon ) (:)</strong>
            </div>
            <div className="def">
              जैसे निर्देशक चिह्न ( — ) मार्गदर्शन देता है, वैसे ही यह चिह्न भी
              प्रयुक्त होता है; अधिकतर इसका प्रयोग शीर्षकों में किया जाता है।
              जैसे - <b>महात्मा गांधी ने कहा: "सत्य ही ईश्वर है।"</b>
            </div>
            <br></br>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AltheoryMidContent1;
